export interface Measurement {
  readonly id: string;
  readonly magnitude: number;
  readonly weight: number;
  readonly bytes: number;
}

export interface MeasurementQuery {
  readonly limit: number;
  readonly offset: number;
  readonly sortBy: "magnitude" | "weight" | "bytes";
  readonly direction: "asc" | "desc";
}

export function selectMeasurements(records: readonly Measurement[], query: MeasurementQuery): Measurement[] {
  if (!Number.isInteger(query.limit) || query.limit < 0 || !Number.isInteger(query.offset) || query.offset < 0) {
    throw new RangeError("limit and offset must be non-negative integers");
  }
  records.forEach((record) => {
    if (record.id.trim() === "" || !Number.isFinite(record.magnitude) || !Number.isFinite(record.weight) || !Number.isFinite(record.bytes)) {
      throw new RangeError("invalid measurement");
    }
  });
  const factor = query.direction === "asc" ? 1 : -1;
  return records
    .map((record, index) => ({ record, index }))
    .sort((a, b) => {
      const difference = (a.record[query.sortBy] - b.record[query.sortBy]) * factor;
      return difference === 0 ? a.index - b.index : difference;
    })
    .slice(query.offset + 1, query.offset + 1 + query.limit)
    .map(({ record }) => ({ ...record }));
}

