import { selectMeasurements } from './solution';
import type { Measurement, MeasurementQuery } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsRange(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}
function ids(records: readonly Measurement[]): string {
  return records.map((record) => record.id).join(',');
}

const records: Measurement[] = [
  { id: 'a', magnitude: 2, weight: 5, bytes: 30 },
  { id: 'b', magnitude: 1, weight: 5, bytes: 10 },
  { id: 'c', magnitude: 2, weight: 3, bytes: 20 },
  { id: 'd', magnitude: 4, weight: 1, bytes: 40 }
];
const before = records.map((record) => ({ ...record }));
const asc: MeasurementQuery = { limit: 3, offset: 0, sortBy: 'magnitude', direction: 'asc' };
const selected = selectMeasurements(records, asc);
equal(ids(selected), 'b,a,c', 'ascending sort is stable for ties');
assert(selected.every((record) => !records.includes(record)), 'returned records are fresh objects');
assert(records.every((record, i) => record.id === before[i].id && record.magnitude === before[i].magnitude && record.weight === before[i].weight && record.bytes === before[i].bytes), 'input records and order are unchanged');
(records[0] as { magnitude: number }).magnitude = 99;
equal(selected[1].magnitude, 2, 'result does not alias input records');

const descending = selectMeasurements(before, { limit: 2, offset: 1, sortBy: 'bytes', direction: 'desc' });
equal(ids(descending), 'a,c', 'offset follows descending sort and limit caps output');
equal(selectMeasurements(before, { limit: 0, offset: 0, sortBy: 'weight', direction: 'asc' }).length, 0, 'zero limit returns empty');
equal(selectMeasurements(before, { limit: 4, offset: 4, sortBy: 'weight', direction: 'asc' }).length, 0, 'offset at length returns empty');
equal(selectMeasurements(before, { limit: 4, offset: 20, sortBy: 'weight', direction: 'asc' }).length, 0, 'offset beyond length returns empty');
equal(selectMeasurements([], { limit: 2, offset: 0, sortBy: 'bytes', direction: 'asc' }).length, 0, 'empty records return empty');

for (const limit of [-1, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsRange(() => selectMeasurements(before, { limit, offset: 0, sortBy: 'bytes', direction: 'asc' }), 'invalid limit rejected');
}
for (const offset of [-1, 0.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsRange(() => selectMeasurements(before, { limit: 1, offset, sortBy: 'bytes', direction: 'asc' }), 'invalid offset rejected');
}
throwsRange(() => selectMeasurements([{ id: ' ', magnitude: 1, weight: 1, bytes: 1 }], asc), 'blank ID rejected');
throwsRange(() => selectMeasurements([{ id: 'x', magnitude: Number.NaN, weight: 1, bytes: 1 }], asc), 'NaN magnitude rejected');
throwsRange(() => selectMeasurements([{ id: 'x', magnitude: 1, weight: Number.POSITIVE_INFINITY, bytes: 1 }], asc), 'infinite weight rejected');
throwsRange(() => selectMeasurements([{ id: 'x', magnitude: 1, weight: 1, bytes: Number.NEGATIVE_INFINITY }], asc), 'infinite bytes rejected');

